# CS/pages/ui.R  --  The CS user interface: page tools, the Standard pages and the set-up flow pages.
# Sourced by app.R at the top level (local = TRUE); the Workbench (workbench/wb_cs.R) reuses these pages.

station_picker <- function(id, label) selectizeInput(id, label, choices = NULL, width = "100%",
  options = list(create = TRUE, placeholder = "Choose a station or type a new name"))
res_choices <- c("Every record" = "raw", "Hourly mean" = "hour", "Daily mean" = "day", "Monthly mean" = "month")

if (dir.exists(file.path(APP_DIR, "docs"))) addResourcePath("docs", file.path(APP_DIR, "docs"))
# The folder and run settings (Home in the Standard interface, Import data in the Workbench).
std_folders <- function() fluidRow(
        column(7, div(class = "panel-x",
          h3("Folders"),
          textAreaInput("raw_dirs", "Raw .dat folders, one per line", paste(SETTINGS$raw_dirs, collapse = "\n"), rows = 3, width = "100%"),
          ovid_browse_button("raw_dirs"), uiOutput("raw_check"),
          textInput("project_dir", "Project folder (set-up tables and output are kept here)", SETTINGS$project_dir, width = "100%"), ovid_browse_button("project_dir"),
          textInput("skip_tables", "Logger tables to leave out", paste(SETTINGS$skip_tables, collapse = ", "), width = "100%"),
          ovid_switch("import_cr10x", "Include CR10X files (headerless mixed-array)", isTRUE(SETTINGS$import_cr10x), width = "100%"),
          ovid_switch("incremental", "Reuse loggers and stations whose files and set-up have not changed (much faster; uses disk space in the project's cache folder)", !isFALSE(SETTINGS$incremental), width = "100%"),
          selectInput("station_format", "Save station files as", width = "100%", selected = SETTINGS$station_format,
                      c("CSV" = "csv", "Parquet (smaller, faster plots)" = "parquet", "Both" = "both")),
          p(class = "dim", style = "margin:0", "New download from the field? Drop the files into one of these folders and press Run pipeline at the top right."))),
        column(5, div(class = "panel-x", h3("Share with colleagues"),
            p(class = "dim", "Builds a folder with the app and the current output that opens in viewer mode: colleagues can plot, read statistics and download reports, but cannot change the set-up or run the pipeline. Publish that folder to Posit."),
            checkboxInput("vb_detail", "Include every individual audit entry (larger)", FALSE, width = "100%"),
            actionButton("vb_build", "Build viewer bundle", icon = icon("box-archive")), uiOutput("vb_out"))))
std_css <- function() paste(gb_css, legible_css(good = "--green"),
                            sprintf(".d-top{border-bottom-color:%s} .d-rail{border-right-color:%s}", GB$line, GB$line))   # olive-crt's window separators
std_head <- function() tagList(tags$link(rel = "stylesheet", href = "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css"),
                 tags$script(src = "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"), tags$script(src = "map_tools.js"), tags$script(src = "cs_map.js"),
                 tags$script(HTML("
    var csSize=null; try{csSize=localStorage.getItem('cs_plot_size');}catch(e){}
    $(document).on('shiny:connected',function(){ if(csSize) Shiny.setInputValue('size_stored',csSize,{priority:'event'}); });
    $(document).on('shiny:inputchanged',function(e){ if(e.name==='plot_size'&&e.value){try{localStorage.setItem('cs_plot_size',e.value);}catch(x){}} });")),
                 if (exists("useBusyIndicators", asNamespace("shiny"))) shiny::useBusyIndicators(spinners = FALSE, pulse = TRUE),
                 if (VIEWER) tags$script(HTML("document.addEventListener('DOMContentLoaded',function(){document.documentElement.classList.add('viewer')});")))
# The Standard pages: the tools and section labels for ovid_page(), in rail order. The Workbench shows the same
# pages in its own frame (workbench/wb_cs.R); there sources = FALSE leaves the folder settings off Home, as its Import
# view holds them.
std_pages <- function(sources = TRUE) list(
    ovid_tool("Home", icon = "house",
      tagList(h2("Field data hub"), p(class = "lede", 
                if (VIEWER) "A read-only view of the cleaned logger records: plot them, look at the statistics, see what was removed and why, and download reports."
                else "Everything downloaded from the field in one place: stitch it, plot it, check it, clean it, and write it up. Raw files are never changed.")),
      cs_home_ui(),                                                         # CS/home.R: before import, and the station picked on the strip
      uiOutput("stats"),
      h4("Stations"), p(class = "dim", "Click a station to open it in Plot and explore."), DTOutput("home_st"),
      h4("What each logger covers"),
      div(class = "scrollbox", plotOutput("timeline", height = "auto")),
      if (!VIEWER) fluidRow(
        column(6, div(class = "d-cardx", h3("Next time"), p("Put the new files from the field into one of the raw folders and press ", tags$b("Run pipeline"), ". Only new and changed files are read; everything set up here is used again."),
          tags$a(href = "#", `data-ovid-go` = "Raw files", "Bring in new files \u203a"))),
        column(6, div(class = "d-cardx", h3("Recent changes"), uiOutput("saved_hist")))),
      if (!VIEWER && sources) p(class = "dim", "The data folders are on ", tags$a(href = "#", `data-ovid-go` = "Project", "1 Project"), "."),
      tags$details(class = "editor-only", tags$summary("Log of the last run"), uiOutput("log")),
      uiOutput("ver"),
      div(class = "foot", "Output is written to the project folder: output/stations (clean data), output/derived (summaries), output/precip (gauges), output/audit (audit trail and metadata).")),

    "View",

    ovid_tool("Plot and explore", value = "Explore", icon = "chart-line",
      page_head("Plot and explore", "Each station is one continuous record per parameter, stitched from every file and logger table it has. Over time opens on three months: drag across it to select a stretch for its figures or to remove its values, and drag the time axis or scroll to move through the rest. The files behind what you see are listed under the plot."),
      tabsetPanel(id = "ex_tab",
        tabPanel("One station",
          ovid_controls(
            selectInput("ex_station", "Station", choices = NULL, width = "100%"),
            tagAppendAttributes(selectizeInput("ex_params", "Parameters", choices = NULL, multiple = TRUE, width = "100%"), class = "d-wide"),
            dateRangeInput("ex_dates", "Period", width = "100%"),
            selectInput("ex_kind", "Chart", width = "100%",
                                    list(`Through time` = c("Over time" = "ts", "Daily range (min, mean, max)" = "band", "Each year overlaid" = "years", "Calendar (year by day)" = "calendar", "Running total" = "cum"),
                                         `Patterns` = c("Month by month (box plots)" = "box", "Average day (by hour)" = "diurnal", "Time of day by date" = "daily", "Wind rose" = "windrose"),
                                         `Distribution` = c("Spread of values (histogram)" = "hist", "How often a value is exceeded" = "duration", "One against another" = "scatter"))),
            selectInput("ex_res", "Show as", res_choices, width = "100%"),
            ovid_split_toggle("ex_split", "Plot and summary")),
          conditionalPanel("input.ex_kind == 'years'", div(class = "btnrow", style = "margin:-4px 0 8px",
            selectInput("ex_ystart", "Year runs from", c("1 January" = "1", "1 September" = "9", "1 October (water year)" = "10"), "1", width = "220px"),
            radioButtons("ex_ymode", "Show", c("Values" = "value", "Difference from the average year" = "anom"), "value", inline = TRUE))),
          uiOutput("ex_fit"),
          div(class = "btnrow", style = "margin:0 0 6px", span(class = "push"),
              downloadButton("ex_png", "Export plot (PNG)"), downloadButton("ex_dl", "Export data (CSV)")),
          div(class = "btnrow", style = "margin:-2px 0 8px", checkboxGroupInput("ex_marks", NULL, inline = TRUE, selected = c("batt", "flags", "log"),
                c("Shade low battery" = "batt", "Shade suspect values" = "flags", "Mark field-log entries" = "log"))),
          ovid_split("ex_split", width = "32%", tagList(ovid_focus(uiOutput("ex_plot_ui"), class = "cs-plotcard"), uiOutput("ex_brush_ui")),
                       tableOutput("ex_stats"), side_title = "Summary of the selection"),
          h4("Files this record is built from"), uiOutput("ex_src_note"), DTOutput("ex_src"), uiOutput("ex_about")),
        tabPanel("Compare stations",
          ovid_controls(
            selectizeInput("cp_param", "Parameter", choices = NULL, width = "100%"),
            tagAppendAttributes(selectizeInput("cp_stations", "Stations", choices = NULL, multiple = TRUE, width = "100%"), class = "d-wide"),
            selectInput("cp_res", "Records", res_choices[-1], selected = "hour", width = "100%"),
            selectInput("cp_diff", "Difference from", c("(none)" = ""), width = "100%"),
            ovid_switch("cp_same", "Same scale for every station", TRUE, width = "100%"),
            downloadButton("cp_dl", "Export CSV")),
          ovid_focus(uiOutput("cp_plot_ui"), class = "cs-plotcard"), tableOutput("cp_stats")),
        tabPanel("Summaries",
          p(class = "dim", "Daily, monthly and water-year values for the station chosen on the first tab. A value is given only when at least 80 % of the expected records (or days) are present, so a half-recorded day does not pass as a daily mean. Totals are summed; everything else is averaged. Break down by gives numbers from every record in the period instead: the whole period at a glance, or one statistic by year, calendar month or water year."),
          div(class = "btnrow", radioButtons("su_kind", NULL, inline = TRUE, c("Daily" = "daily", "Monthly" = "monthly", "Water year" = "water_year")),
              selectInput("su_cols", NULL, c("Chosen parameters and derived values" = "sel", "Every column" = "all"), width = "300px"),
              selectInput("su_by", "Break down by", c("Nothing (the summary table)" = "", "Whole period" = "all", "Year" = "year", "Calendar month" = "month", "Water year" = "wy"), width = "220px"),
              conditionalPanel("input.su_by != '' && input.su_by != 'all'", selectInput("su_stat", "Statistic", STAT_WHAT, width = "180px")),
              span(class = "push", downloadButton("su_dl", "Export full table (CSV)"))),
          uiOutput("su_note"), ovid_focus(uiOutput("su_plot_ui")), DTOutput("su_tbl")),
        tabPanel("Against the neighbours",
          p(class = "dim", "Each station's daily means set against the median of the other stations (the parameters of the between-station check; never precipitation). Nothing here changes a station table."),
          h4("Breakpoints"), p(class = "dim", "Pettitt's test for one change in the monthly difference from the other stations, so weather common to all of them cancels: a shift points at a sensor swap, a move, a recalibration or a drifting sensor. Reported, never adjusted. Needs three stations and two years."),
          DTOutput("hb_tbl"),
          h4("Estimated daily means"), p(class = "dim", "Missing daily means estimated from the station that tracks them best (a straight line fitted on the days both have; r\u00b2 at least 0.9 over 60 days or more, gaps up to a month). Level L3, WMO code 6. Kept apart in output/derived/daily_estimated.csv."),
          DTOutput("he_tbl")),
        tabPanel("Data availability",
          p(class = "dim", "Share of days with a daily value each month, for every station. A day counts when at least 80 % of its records are there."),
          ovid_focus(uiOutput("av_plot_ui"), class = "cs-plotcard")))),

    ovid_tool("Sensor health", value = "Health", icon = "heart-pulse",
      page_head("Sensor health", "Every parameter of every station table, worst first: dead (no values), stopped before the table ends, failing (most values removed), dying (values thin out towards the end), stuck (unchanged for days), intermittent (more than 10% missing or 2% removed) or suspect (more than 10% flagged). Rain and other totals, and snow depth at zero through the summer, are never called stuck."),
      uiOutput("sh_empty"),
      div(class = "panel-x", fluidRow(column(5, selectizeInput("sh_station", "Stations (blank = all)", choices = NULL, multiple = TRUE, width = "100%")),
                                      column(3, div(style = "margin-top:26px", ovid_switch("sh_bad", "Only those that are not ok", TRUE))))),
      DTOutput("sh_tbl"), p(class = "dim", "Click a row to plot that parameter on Plot and explore.")),

    ovid_tool("Precipitation", icon = "cloud-rain",
      page_head("Precipitation", "Weighing gauges (OTT Pluvio2, Geonor T-200B) need more than range limits: the bucket is emptied and topped up, the running total rolls over and resets. This page turns the bucket record into precipitation and shows how."),
      uiOutput("pr_empty"),
      div(class = "panel-x", fluidRow(
        column(3, selectInput("pr_gauge", "Gauge", choices = NULL, width = "100%")),
        column(3, selectInput("pr_chart", "Chart", width = "100%",
                              c("Daily totals" = "daily", "Every record" = "interval", "Cumulative" = "cum", "Monthly totals" = "month",
                                "Yearly totals" = "year", "Each year overlaid (cumulative)" = "cumyear", "Bucket content and servicing" = "bucket",
                                "Running total minus bucket (daily)" = "diff", "Quality flags by month" = "flags"))),
        column(3, checkboxGroupInput("pr_series", "Series", inline = TRUE, c("Final" = "precip_mm", "Running total" = "precip_acc_total_mm", "Bucket cummax" = "precip_bucket_mm", "Wind-corrected" = "precip_corrected_mm"), selected = "precip_mm")),
        column(3, dateRangeInput("pr_dates", "Period", width = "100%")))),
      uiOutput("pr_cards"),
      ovid_focus(uiOutput("pr_plot_ui")),
      div(class = "btnrow", style = "margin-top:6px", span(class = "push", downloadButton("pr_png", "Export plot (PNG)"), downloadButton("pr_dl", "Export full table (CSV)"))),
      tabsetPanel(id = "pr_tabs",
        tabPanel("By year", DTOutput("pr_yearly")),
        tabPanel("By water year", p(class = "dim", "1 October to 30 September, named for the year it ends in."), DTOutput("pr_wy")),
        tabPanel("Gaps", DTOutput("pr_gaps")),
        tabPanel("Servicing", DTOutput("pr_serv")),
        tabPanel("Bucket cycles", DTOutput("pr_cycles")),
        tabPanel("Events", DTOutput("pr_events")),
        tabPanel("Method", uiOutput("pr_method")),
        tabPanel("Gauge set-up", div(class = "editor-only",
          p(class = "dim", "Gauges are recognised from their column names when the pipeline runs (", code("acc_total"), " + ", code("bucket_nr"), " for a Pluvio2, ", code("GN_mm"),
            " for a Geonor). Add one by hand when the columns are named differently, for example an unlabelled CR10X array."),
          fluidRow(
            column(3, selectInput("pg_station", "Station and stream", choices = NULL, width = "100%")),
            column(2, selectInput("pg_type", "Gauge", c("OTT Pluvio2" = "pluvio2", "Geonor T-200B" = "geonor"), width = "100%")),
            column(2, selectInput("pg_bucket", "Bucket content (mm)", choices = NULL, width = "100%")),
            column(2, selectInput("pg_acc", "Running total", choices = NULL, width = "100%")),
            column(2, selectInput("pg_status", "Status code", choices = NULL, width = "100%")),
            column(1, div(style = "margin-top:24px", actionButton("pg_add", "Add", class = "btn-primary")))),
          p(class = "dim", "Each gauge is one row of the table below. The bucket-only window (", code("bucket_only"), " yes, with ", code("bucket_only_start"), " and ", code("bucket_only_end"),
            ") makes the bucket weight the only precipitation signal between those dates; ", code("final_source"), " bucket uses bucket cummax throughout (blank: the running total where it is healthy). Save, then press Reprocess."),
          editUI("gauges"),
          div(class = "btnrow", actionButton("pr_rerun", "Reprocess precipitation only", icon = icon("rotate"), class = "btn-primary d-once"),
              span(class = "dim", "Uses the station tables from the last run, so it takes seconds. Save changes first.")))))),

    ovid_tool("Combined records", value = "Composite", icon = "layer-group",
      page_head("Combined records", "One parameter stitched from several stations into a single record, for example air temperature from Site A up to a sensor change and from Site B after it. Each source can be limited to a stretch of time and given an offset; where two sources both have a value, the one higher in the list wins. Every value keeps the station it came from. Saved records are rebuilt on every run into output/composites."),
      uiOutput("cb_empty"),
      div(class = "panel-x", fluidRow(
        column(3, selectizeInput("cb_name", "Combined record", choices = NULL, width = "100%", options = list(create = TRUE, placeholder = "Choose, or type a new name"))),
        column(3, selectizeInput("cb_param", "Parameter", choices = NULL, width = "100%")),
        column(2, selectInput("cb_step", "Time step", c("Every record" = "", "Hourly mean" = "hour", "Daily mean" = "day"), width = "100%")),
        column(4, div(class = "btnrow", style = "margin-top:24px", actionButton("cb_save", "Save", class = "btn-primary editor-only"), actionButton("cb_delete", "Delete", class = "btn-danger editor-only"),
                      downloadButton("cb_dl", "Export CSV"))))),
      h4("Sources, most preferred first"),
      div(class = "panel-x", fluidRow(
        column(3, selectizeInput("cb_station", "Station", choices = NULL, width = "100%")),
        column(2, selectInput("cb_stream", "Table", choices = c("Every table" = ""), width = "100%")),
        column(2, textInput("cb_start", "From", placeholder = "YYYY-MM-DD", width = "100%")),
        column(2, textInput("cb_end", "To", placeholder = "YYYY-MM-DD", width = "100%")),
        column(1, textInput("cb_offset", "Offset", placeholder = "0", width = "100%")),
        column(2, div(style = "margin-top:24px", actionButton("cb_add", "Add source", icon = icon("plus"))))),
        div(class = "btnrow", actionButton("cb_up", "Move up", icon = icon("arrow-up")), actionButton("cb_down", "Move down", icon = icon("arrow-down")), actionButton("cb_rm", "Remove"),
            span(class = "dim", "Select a source to move or remove it. Double-click a cell to change its dates or offset."))),
      DTOutput("cb_src"),
      ovid_focus(plotOutput("cb_plot", height = "380px")),
      h4("What each source supplied"),
      p(class = "dim", tags$b("median difference"), " is this source minus the record where it overlaps a source preferred to it: a guide for its offset."),
      DTOutput("cb_used")),

    ovid_tool("Station map", value = "Map", icon = "map",
      page_head("Station map", "Where each station is, from latitude and longitude in Station details (typed in on Sites and field log, or brought in with a configuration file on the Configuration page; the deployment sheet's coordinates are not used here). The colour shows whether a station is still recording. Click a station for its records and a link to plot it."),
      uiOutput("map_note"),
      div(class = "btnrow", radioButtons("map_show", NULL, inline = TRUE, c("Stations with data" = "data", "Every station with coordinates" = "all")),
          ovid_switch("map_labels", "Station names", TRUE)),
      ovid_focus(div(id = "cs_map", style = "height:640px;border-radius:8px;border:1px solid var(--bg2)")),
      h4("Stations with data but no coordinates"), DTOutput("map_missing")),

    "Clean",

    ovid_tool("Raw files", icon = "folder-open", rail = !VIEWER,
      page_head("Raw files", "Every .dat file that was found: where its records went and what was dropped from it. Select a file to look at its data, send it to a different station, leave it out, or remove a bad stretch. Raw files are never changed; each choice is a rule that is applied, and audited, on the next run."),
      uiOutput("rf_empty"),
      div(class = "btnrow", radioButtons("rf_show", NULL, inline = TRUE, c("All files" = "all", "Read" = "ok", "Not read" = "bad", "With a rule" = "rule", "With dropped or conflicting records" = "drop")),
          span(class = "push", downloadButton("rf_dl", "Export CSV"))),
      DTOutput("rf_tbl"),
      uiOutput("rf_detail"),
      tags$details(class = "editor-only", tags$summary("Rules for single files"),
        p(class = "dim", style = "margin-top:8px", code("action"), " is ", code("assign"), " (send the file to ", code("station"), " / ", code("stream"), ") or ", code("ignore"),
          " (leave the file out). ", code("table"), " may be left blank to mean every table in the file."), editUI("filerules"))),

    ovid_tool("Clock checks", icon = "clock",
      page_head("Clock checks", "A power loss or a clock fault leaves marks in the timestamps. These are the ones found in the last run. Select a finding to see what it means and to correct it."),
      uiOutput("ck_summary"),
      div(class = "btnrow", selectInput("ck_type", NULL, c("Every kind of finding" = "all"), width = "320px"),
          span(class = "push", downloadButton("ck_dl", "Export CSV"))),
      DTOutput("ck_tbl"),
      uiOutput("ck_fix"),
      tags$details(class = "editor-only", tags$summary("Corrections already set"),
        p(class = "dim", style = "margin-top:8px", code("action"), " is ", code("shift"), " (move timestamps by ", code("shift_minutes"), ") or ", code("remove"),
          ". ", code("start"), " and ", code("end"), " refer to the timestamps as written in the raw file. Every correction is recorded in the audit trail."),
        editUI("timecorr")),
      tags$details(class = "editor-only", tags$summary("Time zones"),
        p(class = "dim", style = "margin-top:8px", "The zone a logger's clock was in, for many files at once. Fill in any of ", code("serial"), ", ", code("model"), ", ",
          code("file_pattern"), " (a folder or part of the path) and ", code("start"), "/", code("end"), " (the file's first reading falls in this span); blank matches anything. ",
          code("offset_hours"), ": -7, 0, -6 ... The first matching row wins. Files are moved into their station's zone (", code("utc_offset_hours"),
          " in Station details, else the time zone in Settings)."),
        editUI("timezones"))),

    ovid_tool("Quality rules", icon = "filter", rail = !VIEWER,
      page_head("Quality rules", "Values outside these limits are removed and written to the audit log with the old value and the rule that removed it."),
      tabsetPanel(id = "qr_tabs",
        tabPanel("Automatic limits", p(class = "dim", "Each pattern matches parameter names. A row with ", code("applies_to"), " (station names or logger numbers separated by |) covers only those, and there it replaces the general limit for the same parameter. ", code("max_spike"), " catches single points that jump by more than that amount and back. ", code("max_flat_hours"),
          " flags a sensor that reports the same value for longer than that. ", code("action"), ": leave blank for the default (limits and spikes remove the value, a flat line only flags it), ",
          code("flag"), " to keep every value and flag it, ", code("remove"), " to remove flat lines too. ", code("max_step_per_hour"), " flags (never removes) a change faster than that between two readings."),
          p(class = "dim", "New projects start with wide spike and step limits that catch sensor glitches, not weather (Zahumensky 2004; Estevez et al. 2011). A project made before them keeps its table as it is; ",
            "the button fills only blank spike and step cells of the standard rows, and you can change or clear any of them."),
          div(class = "btnrow editor-only d-hide-std", actionButton("qc_suggest", "Fill in suggested spike and step limits", icon = icon("wand-magic-sparkles"))),
          editUI("qc")),
        tabPanel("Corrections over a period", period_help(), p(class = "dim", code("stream"), ": one stream of the station (blank: all). ", code("output"), ": for offset, scale or drift of one parameter, ",
          "a column to write the result to, keeping the original (a tipping bucket: parameter ", code("rain_tips"), ", output ", code("rain"), ", scale = mm per tip). ",
          "Removals, calibrations and drift are rows of this table. What each run applied is listed in ", code("output/audit/calibrations_applied.csv"), "."), editUI("period")),
        tabPanel("Calibration options", p(class = "dim", "Values the derived variables use, each with its source. ", code("choice"), ": ", code("default"), " (the literature value), ",
          code("scotty_creek"), " (the published Scotty Creek value, where there is one) or ", code("custom"), " (your ", code("number"), "; a ", code("source"), " is encouraged but not required). ",
          code("applies_to"), ": a station, or * for all; a station's row wins over *. Copy a row to give one station its own value."), editUI("calib")))),

    ovid_tool("Audit trail", value = "Audit", icon = "clipboard-check",
      page_head("Audit trail", "Nothing leaves the data without a line here. Read it top to bottom: what happened in total, why, where, and then the individual records and values."),
      uiOutput("au_cards"),
      h4("1. What was done, and why"),
      p(class = "dim", "One line per kind of change. Click a line to see what it means, what to do about it, and where it happened."),
      DTOutput("au_rules"),
      uiOutput("au_explain"),
      h4("2. Where it happened"),
      div(class = "btnrow", uiOutput("au_scope", inline = TRUE),
          div(style = "width:260px", selectizeInput("au_station", NULL, "All", width = "100%", options = list(placeholder = "Station or logger"))),
          div(style = "width:220px", selectizeInput("au_column", NULL, "All", width = "100%", options = list(placeholder = "Column"))),
          span(class = "push", downloadButton("au_dl", "Export CSV"))),
      uiOutput("au_plot_ui"),
      uiOutput("au_count"), DTOutput("au_tbl"),
      h4("3. The individual records and values"),
      p(class = "dim", "Each entry has the timestamp, the old value, the reason and the source file. Pick a line in step 1, or a station, to keep the list short."),
      uiOutput("au_detail_ui"), DTOutput("au_detail")),

    "Report",

    ovid_tool("Reports and export", value = "Export", icon = "file-export",
      page_head("Export", "One zip that can be used without the app: a tidy CSV per station table with flag columns, daily and monthly summaries, a report per table (HTML, PDF or both), and a readme that explains the columns."),
      uiOutput("xp_empty"),
      div(class = "panel-x", fluidRow(
        column(6, selectizeInput("xp_keys", "Station tables", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "Pick one or more")),
               div(class = "btnrow", style = "margin-top:0", actionLink("xp_all", "Select all"), actionLink("xp_none", "Clear"))),
        column(3, dateRangeInput("xp_dates", "Period (leave as is for everything)", width = "100%")),
        column(3, checkboxGroupInput("xp_opts", "Include", c("Quality flags" = "flags", "Daily, monthly and water-year summaries" = "summaries", "A report per table" = "report",
